use vstd::prelude::*;

verus! {
    fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
        requires
            // The original list has at least two elements,
            // and k is 1-based, strictly between 1 and list.len().
            list.len() >= 2,
            k >= 1,
            k < list.len(),
        ensures
            // The new list has length one less.
            new_list.len() == list.len() - 1,
        ensures
            // For every position j in the new list,
            // if j < k-1 then it comes from list[j],
            // otherwise it comes from list[j+1].
            forall |j: usize| j < new_list.len() ==>
                if j < k - 1 {
                    new_list[j] == list[j]
                } else {
                    new_list[j] == list[j + 1]
                },
    {
        let n = list.len();
        let pos = k - 1; // 0-based index to remove
        let mut new_list: Vec<i32> = Vec::with_capacity(n - 1);
        let mut i: usize = 0;
        while i < n
            invariant
                // i has advanced between 0 and n
                i <= n,
                // new_list.len() equals i if we haven't yet reached pos,
                // otherwise it equals i-1 because we skipped one element
                new_list.len() == if i <= pos { i } else { i - 1 },
                // and up to new_list.len() we already have exactly
                // the original list with the element at pos removed
                forall |j: usize| j < new_list.len() ==>
                    if j < pos {
                        new_list[j] == list[j]
                    } else {
                        new_list[j] == list[j + 1]
                    },
            decreases n - i
        {
            if i == pos {
                // skip the element at position pos
                i = i + 1;
            } else {
                // copy list[i] into new_list
                let v = list[i];
                new_list.push(v);
                i = i + 1;
            }
        }

        // at the end, i == n, so new_list.len() == n-1
        new_list
    }
}

fn main() {
    // example usage
    let v = vec![10, 20, 30, 40];
    // remove the 2nd element (20), yields [10,30,40]
    let w = remove_kth_element(&v, 2);
    assert!(w == vec![10, 30, 40]);
}